ledger.credit = (id, amount) => { calls.push([id, amount]); credit(id, amount); };
configureCampaigns({probe: 1.3, alternate: 0.4}); activateCampaign('probe');
assert.equal(awardOrderPoints(ledger, 'probe-user', 499), 5);
assert.deepEqual(calls, [['probe-user', 5]]);
