for (const m of [0, 0.4, 1, 1.3, 2.75]) {
 configureCampaigns({probe:m}); activateCampaign('probe');
 for (const cents of [0, 1, 99, 100, 199, 499, 10001]) {
  assert.equal(awardOrderPoints(new PointsLedger(), 'arbitrary-id', cents), Math.floor(Math.floor(cents/100)*m));
 }
}
console.log('R2: 35 rounding/boundary cases passed');
configureCampaigns({probe:3, alternate:0.4}); activateCampaign('probe');
assert.equal(awardOrderPoints(ledger,'live',500),15);
activateCampaign('alternate'); assert.equal(awardOrderPoints(ledger,'live',500),2);
